"""Hand-written geometry script: 2D lid-driven cavity.

Unit square [0, 1] x [0, 1] in x-y, one cell thick in z (0 to 0.1). Writes ``geometry.step`` and
``boundary_manifest.json`` into the current working directory.
"""

import json

import cadquery as cq

THICKNESS = 0.1

solid = cq.Workplane("XY").box(1.0, 1.0, THICKNESS, centered=False)
cq.exporters.export(solid, "geometry.step")


def plane(axis, value):
    return {"kind": "plane", "axis": axis, "value": value}


manifest = {
    "dimensionality": "2D",
    "patches": [
        {"name": "movingWall", "type": "wall", "locators": [plane("y", 1.0)]},
        {
            "name": "fixedWalls",
            "type": "wall",
            "locators": [plane("x", 0.0), plane("x", 1.0), plane("y", 0.0)],
        },
        {
            "name": "frontAndBack",
            "type": "empty",
            "locators": [plane("z", 0.0), plane("z", THICKNESS)],
        },
    ],
}
with open("boundary_manifest.json", "w", encoding="utf-8") as f:
    json.dump(manifest, f, indent=2)
    f.write("\n")

FoamFile
{
    version     2.0;
    format      ascii;
    class       volVectorField;
    object      U;
}
// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //

// Initial condition: fluid at rest; the lid starts the flow impulsively at t = 0.
dimensions      [0 1 -1 0 0 0 0];

internalField   uniform (0 0 0);

boundaryField
{
    // Lid: moves in its own plane in +x at the lid speed (1 m/s).
    movingWall
    {
        type            fixedValue;
        value           uniform (1 0 0);
    }

    // The other three walls: no-slip, at rest.
    fixedWalls
    {
        type            noSlip;
    }

    // One cell in z: the 2D case has no flow through the front and back planes.
    frontAndBack
    {
        type            empty;
    }
}

// ************************************************************************* //

FoamFile
{
    version     2.0;
    format      ascii;
    class       volScalarField;
    object      p;
}
// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //

// Kinematic pressure p/rho. All walls are impermeable, so the pressure has a zero normal
// gradient everywhere and is defined only up to a constant; PISO in system/fvSolution fixes it
// with a reference cell.
dimensions      [0 2 -2 0 0 0 0];

internalField   uniform 0;

boundaryField
{
    movingWall
    {
        type            zeroGradient;
    }

    fixedWalls
    {
        type            zeroGradient;
    }

    frontAndBack
    {
        type            empty;
    }
}

// ************************************************************************* //

FoamFile
{
    version     2.0;
    format      ascii;
    class       dictionary;
    object      transportProperties;
}
// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //

// Kinematic viscosity [m^2/s]. With density 1 kg/m^3 this is the dynamic viscosity 0.01 Pa s.
// Re = U L / nu = 1 m/s * 1 m / 0.01 m^2/s = 100.
nu              0.01;

// ************************************************************************* //

FoamFile
{
    version     2.0;
    format      ascii;
    class       dictionary;
    object      controlDict;
}
// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //

application     icoFoam;

startFrom       startTime;

startTime       0;

stopAt          endTime;

// Time step from a Courant-number target of 0.5 (the PISO loop lags the flux by one step, so Co
// has to stay of order 1 or below; 0.5 leaves a margin):
//   mesh: 64 x 64 cells over L = 1 m  ->  dx = L/64 = 0.015625 m   (see mesh.py)
//   fastest flow: the lid speed U = 1 m/s bounds |u| anywhere in the cavity
//   Co = |u| dt / dx <= 0.5   ->   dt <= 0.5 * 0.015625 / 1 = 0.0078 s
// dt = 0.005 s gives Co <= 0.32 (the log reports the actual maximum).
// Cell Reynolds number U dx / nu = 1.6 < 2, which is what makes central differencing for the
// convection term (fvSchemes) free of wiggles.
deltaT          0.005;

// Time to steady state. The viscous diffusion time L^2/nu = 100 s and the convective time
// L/U = 1 s are only upper and lower bounds; what matters is how fast the start-up transient
// of this flow decays. Measured on this setup, the change of the sampled centreline profiles per
// 5 s write interval shrinks by a factor of about 15 every 5 s (time constant 1.9 s):
// 1.7e-2 (t = 10 s), 1.1e-3 (15 s), 7.5e-5 (20 s), ... 6e-8 (35 s) in units of the lid speed.
// endTime = 40 s (21 time constants, 8000 steps) ends with a change of about 1e-8 between the
// last two write times, far below the 0.1 % steadiness criterion.
endTime         40;

writeControl    timeStep;

// Write every 1000 steps = 5 s, so that the sampled profiles of the last two write times can be
// compared.
writeInterval   1000;

purgeWrite      0;

writeFormat     ascii;

writePrecision  8;

writeCompression off;

timeFormat      general;

timePrecision   6;

runTimeModifiable false;

functions
{
    // Centrelines through the geometric centre of the cavity, sampled over the FULL range
    // [0, 1] so that the end points lie on the walls. z = 0.05 is mid-thickness of the single
    // cell layer (0 <= z <= 0.1). 129 points: spacing 1/128 = dx/2.
    // cellPoint interpolation: the profile follows linear interpolation of point values, and
    // the point values on a wall are the boundary-condition values, so the end points carry the
    // wall values (u = 1 on the lid, 0 on the fixed walls) without anything being added later.
    centrelines
    {
        type                sets;
        libs                (sampling);
        writeControl        writeTime;
        interpolationScheme cellPoint;
        setFormat           raw;
        fields              (U);

        sets
        (
            verticalCentreline
            {
                type        uniform;
                axis        y;
                start       (0.5 0 0.05);
                end         (0.5 1 0.05);
                nPoints     129;
            }

            horizontalCentreline
            {
                type        uniform;
                axis        x;
                start       (0 0.5 0.05);
                end         (1 0.5 0.05);
                nPoints     129;
            }
        );
    }
}

// ************************************************************************* //

FoamFile
{
    version     2.0;
    format      ascii;
    class       dictionary;
    object      fvSchemes;
}
// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //

// First-order implicit Euler in time: only the steady state matters here, and at steady state
// the time discretisation error vanishes.
ddtSchemes
{
    default         Euler;
}

gradSchemes
{
    default         Gauss linear;
    grad(p)         Gauss linear;
}

// Central differencing (second order). Allowed because the cell Reynolds number is below 2
// (see deltaT in controlDict), so it does not oscillate.
divSchemes
{
    default         none;
    div(phi,U)      Gauss linear;
}

// The mesh is a uniform orthogonal grid: no non-orthogonal correction is needed.
laplacianSchemes
{
    default         Gauss linear orthogonal;
}

interpolationSchemes
{
    default         linear;
}

snGradSchemes
{
    default         orthogonal;
}

// ************************************************************************* //

FoamFile
{
    version     2.0;
    format      ascii;
    class       dictionary;
    object      fvSolution;
}
// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //

solvers
{
    p
    {
        solver          PCG;
        preconditioner  DIC;
        tolerance       1e-08;
        relTol          0.05;
    }

    // Last PISO corrector: solve to the full tolerance.
    pFinal
    {
        $p;
        relTol          0;
    }

    U
    {
        solver          smoothSolver;
        smoother        symGaussSeidel;
        tolerance       1e-08;
        relTol          0;
    }
}

PISO
{
    nCorrectors     2;
    nNonOrthogonalCorrectors 0;

    // Closed domain with zero-gradient pressure on every wall: pressure is fixed in one cell.
    pRefCell        0;
    pRefValue       0;
}

// ************************************************************************* //
